        "postlude-android-membership-terms": {
          "items": {
            "postlude-android-membership-terms|manual|text|1": {
              "sourceText": "权威平台认可",
              "translation": "Trusted by leading brands"
            },
            "postlude-android-membership-terms|manual|text|2": {
              "sourceText": "adidas",
              "translation": "adidas"
            },
            "postlude-android-membership-terms|manual|text|3": {
              "sourceText": "PHILIPS",
              "translation": "PHILIPS"
            },
            "postlude-android-membership-terms|manual|text|4": {
              "sourceText": "BMW",
              "translation": "BMW"
            },
            "postlude-android-membership-terms|manual|text|5": {
              "sourceText": "UMAY",
              "translation": "UMAY"
            },
            "postlude-android-membership-terms|manual|text|6": {
              "sourceText": "关于我们的团队",
              "translation": "About our team"
            },
            "postlude-android-membership-terms|manual|text|7": {
              "sourceText": "为个人提供精准且个性化的训练建议与指导，确保训练的准确性与有效性，包括根据个人需求和目标对姿势、动作和训练强度进行个性化调整。",
              "translation": "We give people precise, personalized training advice and guidance to keep workouts accurate and effective, adjusting posture, movement, and intensity to each person's needs and goals."
            },
            "postlude-android-membership-terms|manual|text|8": {
              "sourceText": "你的订阅可随时取消",
              "translation": "Cancel anytime"
            },
            "postlude-android-membership-terms|manual|text|9": {
              "sourceText": "点击继续并选择 Google Pay 支付订阅费用。支付成功后，订阅将以相同套餐和价格自动续费，除非你在当前订阅周期结束前24小时取消。点击继续即表示你同意我们的隐私政策和用户协议。",
              "translation": "Tap Continue and choose Google Pay to pay for your subscription. Once payment succeeds, your subscription renews automatically at the same plan and price unless you cancel at least 24 hours before the current period ends. By tapping Continue, you agree to our Privacy Policy and Terms of Service."
            },
            "postlude-android-membership-terms|manual|text|10": {
              "sourceText": "知道了",
              "translation": "Got it"
            }
          }
        },
